import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import Stream from 'flarum/common/utils/Stream';
import { t } from '../api';
/** One optional sentence: why a call is disputed or turned down. */
export default class ReasonModal extends FormModal {
  text = Stream('');
  className() {
    return 'BingoReasonModal Modal--small';
  }
  title() {
    return this.attrs.title;
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form"
    }, m("p", {
      className: "helpText"
    }, this.attrs.help), m("div", {
      className: "Form-group"
    }, m("textarea", {
      className: "FormControl",
      rows: 3,
      maxlength: 200,
      bidi: this.text,
      "aria-label": this.attrs.help
    })), m("div", {
      className: "Form-group"
    }, m(Button, {
      className: "Button Button--primary Button--block",
      type: "submit",
      loading: this.loading
    }, t('reason.send')))));
  }
  onsubmit(e) {
    e.preventDefault();
    this.loading = true;
    this.attrs.onsubmit(this.text().trim()).then(() => this.hide()).catch(() => {}).finally(() => {
      this.loading = false;
    });
  }
}
flarum.reg.add('ernestdefoe-bingo', 'forum/components/ReasonModal', ReasonModal);